# Parse hex data - filter out non-hex content (debug lines)
lines = hex_data.strip().split('\n')
img_data = []
for line in lines:
    line = line.strip()
    # Skip lines with debug output - only keep pure hex lines (192 hex chars = 96 bytes)
    # Remove spaces and non-hex characters
    hex_only = ''.join(c for c in line if c in '0123456789abcdefABCDEF')
    if len(hex_only) < 192:  # skip short/incomplete lines
        continue
    # Keep only first 192 chars (96 bytes = one complete row)
    hex_only = hex_only[:192]
    pixels = []
    for i in range(0, len(hex_only), 2):
        hex_pair = hex_only[i:i+2]
        pixels.append(int(hex_pair, 16))
    img_data.append(pixels)

img = np.array(img_data, dtype=np.uint8)
print(f"Image shape: {img.shape}")
print(f"Pixel range: min={img.min()}, max={img.max()}, mean={img.mean():.1f}, std={img.std():.1f}")

# Print a sample of the image for visual inspection (ASCII art)
print("\n--- Image visualization (scaled) ---")
# Downsample to fit terminal
step = 6
for y in range(0, img.shape[0], step):
    line = ""
    for x in range(0, img.shape[1], step):
        block = img[y:y+step, x:x+step]
        avg = block.mean()
        # Map 0-255 to ASCII characters
        if avg < 30: c = '#'  # very dark
        elif avg < 50: c = '@'
        elif avg < 65: c = '%'
        elif avg < 80: c = '+'
        elif avg < 100: c = '-'
        elif avg < 130: c = '.'
        elif avg < 170: c = ':'
        else: c = ' '
        line += c
    print(line)

print("\n--- Pixel value distribution ---")
bins = [0, 30, 50, 70, 90, 110, 130, 150, 200, 256]
labels = ['0-30', '30-50', '50-70', '70-90', '90-110', '110-130', '130-150', '150-200', '200-255']
hist, _ = np.histogram(img, bins=bins)
for label, count in zip(labels, hist):
    pct = count / img.size * 100
    bar = '#' * int(pct)
    print(f"  {label:>8s}: {count:6d} ({pct:5.1f}%) {bar}")

# Check if image looks like open or closed eye
# Open eye: top part dark (pupil), bottom bright (sclera)
top = img[:48, :].mean()
bottom = img[48:, :].mean()
print(f"\nTop half mean: {top:.1f}")
print(f"Bottom half mean: {bottom:.1f}")
print(f"Difference: {bottom - top:.1f}")
if bottom - top > 30:
    print("Pattern: Dark top + Bright bottom -> looks like OPEN eye structure")
elif bottom - top < -20:
    print("Pattern: Bright top + Dark bottom -> unusual")
else:
    print("Pattern: Uniform -> looks like CLOSED eye or dark image")
